const $=s=>document.querySelector(s),form=$('#vehicle-form');let configured=false,items=[],editing=null,photos=[],busy=false,comparables=[];
function message(text,error=false){$('#status').textContent=text;$('#status').classList.toggle('error',error);}
async function api(path,method='GET',data){const response=await fetch('/api/'+path,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudo completar la operación.');return result;}
function screen(name){for(const id of ['auth','dashboard','editor'])$('#'+id).hidden=id!==name;message('');}
async function load(){items=await api('admin/inventory');screen('dashboard');$('#logout').hidden=false;$('#summary').textContent=`${items.length} vehículos · ${items.filter(v=>v.status==='available').length} publicados`;$('#list').replaceChildren();for(const v of items){const row=document.createElement('article');row.className='admin-row';if(v.photos[0]){const img=document.createElement('img');img.src=v.photos[0];img.alt=v.name;row.append(img);}const copy=document.createElement('div'),title=document.createElement('h3'),meta=document.createElement('p');title.textContent=v.make+' '+v.name;meta.textContent=`${v.year} · ${{available:'Disponible',draft:'Borrador',sold:'Vendido'}[v.status]} · ${v.price||'Precio a consultar'}`;copy.append(title,meta);const actions=document.createElement('div');actions.className='actions';const edit=document.createElement('button');edit.textContent='Editar';edit.onclick=()=>open(v);const remove=document.createElement('button');remove.textContent='Eliminar';remove.onclick=async()=>{if(!confirm(`¿Eliminar ${v.make} ${v.name}? Esta acción no se puede deshacer.`))return;try{await api('admin/inventory','DELETE',{id:v.id});await load();message('Vehículo eliminado.');}catch(e){message(e.message,true);}};actions.append(edit,remove);row.append(copy,actions);$('#list').append(row);}if(!items.length)$('#list').textContent='Todavía no hay vehículos. Añade el primero para empezar.';}
function photoList(){$('#photo-list').replaceChildren();photos.forEach((url,i)=>{const tile=document.createElement('div');tile.className='photo';const img=document.createElement('img');img.src=url;img.alt='Foto '+(i+1);const cover=document.createElement('button');cover.type='button';cover.textContent=i===0?'Portada':'Usar como portada';cover.disabled=i===0;cover.onclick=()=>{photos.splice(i,1);photos.unshift(url);photoList();};const remove=document.createElement('button');remove.type='button';remove.textContent='Quitar';remove.onclick=()=>{photos.splice(i,1);photoList();};tile.append(img,cover,remove);$('#photo-list').append(tile);});}
function open(v){editing=v?.id||null;form.reset();for(const input of form.elements)if(input.name)input.value=v?.[input.name]||(input.name==='status'?'draft':'');photos=[...(v?.photos||[])];$('#editor-title').textContent=v?'Editar vehículo':'Nuevo vehículo';screen('editor');photoList();}
$('#new').onclick=()=>open();$('#cancel').onclick=()=>{if(!busy)screen('dashboard');};
$('#photos').onchange=async event=>{const files=[...event.target.files];if(files.length+photos.length>12){message('Puedes añadir hasta 12 fotos.',true);event.target.value='';return;}busy=true;$('#save').disabled=true;message('Subiendo fotografías…');try{for(const file of files){if(file.size>8*1024*1024)throw Error(`${file.name}: máximo 8 MB.`);const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('No se pudo leer la foto.'));r.readAsDataURL(file);});photos.push((await api('admin/upload','POST',{image})).url);photoList();}message('Fotos listas. Guarda el vehículo para conservar los cambios.');}catch(e){message(e.message,true);}finally{busy=false;$('#save').disabled=false;event.target.value='';}};
form.onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;$('#save').disabled=true;try{await api('admin/inventory','POST',{...Object.fromEntries(new FormData(form)),id:editing,photos,comparables});await load();message('Guardado. Los disponibles aparecen en la web cliente al actualizarla.');}catch(e){message(e.message,true);}finally{busy=false;$('#save').disabled=false;}};
$('#auth-form').onsubmit=async event=>{event.preventDefault();event.submitter.disabled=true;try{await api('admin/'+(configured?'login':'setup'),'POST',{password:$('#password').value});$('#password').value='';configured=true;await load();}catch(e){message(e.message,true);}finally{event.submitter.disabled=false;}};
$('#logout').onclick=async()=>{try{await api('admin/logout','POST',{});location.reload();}catch(e){message(e.message,true);}};
try{const state=await api('admin/status');configured=state.configured;if(state.authenticated)await load();else if(!configured){$('#auth-title').textContent='Configura tu administrador';$('#auth-copy').textContent='Crea una contraseña de al menos 12 caracteres para administrar esta instalación local.';$('#password').minLength=12;$('#password').autocomplete='new-password';$('#auth-form button').textContent='Crear acceso';}}catch(e){message(e.message,true);}

const models={Toyota:['4Runner','Land Cruiser Prado','Land Cruiser','Hilux','Corolla','Corolla Cross','RAV4','Yaris','Yaris Cross','Rush','Fortuner','Avanza','Tacoma','Tundra'],Ford:['Bronco','Bronco Sport','Ranger','F-150','Explorer','Escape','Territory','Mustang','Everest'],Nissan:['Frontier','Navara','X-Trail','Kicks','Patrol','Versa','Sentra','Qashqai'],Suzuki:['Jimny','Vitara','Grand Vitara','Swift','Baleno','S-Cross','Fronx'],Kia:['Sportage','Sorento','Seltos','Sonet','Picanto','Rio','Cerato'],Hyundai:['Tucson','Santa Fe','Creta','Venue','Accent','Elantra'],Chevrolet:['Tracker','Onix','Captiva','S10','Silverado','Colorado','Tahoe'],Volkswagen:['Amarok','Tiguan','T-Cross','Taos','Golf','Polo'],Honda:['CR-V','HR-V','Civic','Accord','Pilot'],Mazda:['CX-5','CX-30','CX-50','CX-9','BT-50','Mazda3'],Mitsubishi:['Montero','Montero Sport','L200','Outlander','ASX'],Jeep:['Wrangler','Grand Cherokee','Compass','Renegade'],BMW:['X1','X3','X5','Serie 3'], 'Mercedes-Benz':['GLA','GLC','GLE','Clase C'],Audi:['Q3','Q5','Q7','A3','A4'],Subaru:['Forester','Outback','XV','Crosstrek'],Changan:['CS35','CS55','CS75','Hunter'],GWM:['Poer','Wingle','Haval H6','Tank 300'],BYD:['Dolphin','Yuan Plus','Song Plus','Seal']};
function datalist(input,values,id){let list=document.getElementById(id);if(!list){list=document.createElement('datalist');list.id=id;document.body.append(list);}list.replaceChildren(...values.map(value=>{const option=document.createElement('option');option.value=value;return option;}));input.setAttribute('list',id);}
const make=form.elements.make,name=form.elements.name;datalist(make,Object.keys(models),'make-options');function modelOptions(){const key=Object.keys(models).find(k=>k.toLowerCase()===make.value.toLowerCase());datalist(name,models[key]||[],'model-options');}make.addEventListener('input',modelOptions);
for(const [key,label,placeholder] of [['version','Versión / acabado','SR5, Badlands…'],['city','Ciudad','La Paz, Santa Cruz…'],['country','País del mercado','Bolivia'],['condition','Condición','Usado'],['color','Color','Blanco']]){const labelNode=document.createElement('label');labelNode.textContent=label;const input=document.createElement('input');input.name=key;input.placeholder=placeholder;labelNode.append(input);$('.fields').append(labelNode);}
datalist(form.elements.version,['SR5','SR5 Premium','TRD Sport','TRD Off-Road','Limited','Badlands','Wildtrak','Base'],'version-options');
for(const [key,values] of Object.entries({engine:['1.0 Turbo','1.5','1.5 Turbo','1.6','1.8','2.0','2.0 Turbo','2.4 Turbo','2.5','2.7 V6','2.8 Diésel','3.0 Diésel','3.5 V6','4.0 V6','Híbrido','Eléctrico'],type:['SUV','Sedán','Hatchback','Pickup','Coupé','Van','Familiar'],fuel:['Gasolina','Diésel','Híbrido','Eléctrico','GNV'],transmission:['Automática','Manual','CVT','Doble embrague'],condition:['Nuevo','Usado','Seminuevo'],city:['Santa Cruz de la Sierra','La Paz','Cochabamba','Sucre','Tarija','Oruro','Potosí','Trinidad','Cobija'],country:['Bolivia','Chile','Perú','Argentina','Paraguay','Brasil','Estados Unidos'],color:['Blanco','Negro','Gris','Plata','Rojo','Azul','Verde','Beige']}))datalist(form.elements[key],values,key+'-options');
name.addEventListener('input',()=>{const text=name.value.toLowerCase();datalist(form.elements.version,text.includes('bronco')?['Badlands','Wildtrak','Big Bend','Outer Banks','Base']:text.includes('4runner')?['SR5','SR5 Premium','TRD Sport','TRD Off-Road','Limited']:['Base','Sport','Limited','Premium'],'version-options');});
const helper=document.createElement('div');helper.className='editor-help';helper.innerHTML='<strong>Asistente de ficha</strong><p>Empieza por la marca para ver modelos. Las sugerencias son orientativas: puedes escribir cualquier valor y debes confirmar la versión según el año y el mercado.</p><button type="button" id="write-description">Crear descripción con estos datos</button><span id="completion"></span>';form.prepend(helper);
$('#write-description').onclick=()=>{const data=Object.fromEntries(new FormData(form));const text=[`${data.make} ${data.name} ${data.version||''} ${data.year}`.replace(/\s+/g,' ').trim(),...[['Motor','engine'],['Transmisión','transmission'],['Combustible','fuel'],['Kilometraje','mileage'],['Color','color'],['Condición','condition'],['Ubicación','city']].filter(([,key])=>data[key]).map(([label,key])=>`${label}: ${data[key]}.`),'Consulta los detalles y la disponibilidad con Torres Garage.'].join('\n');if(form.elements.description.value&&!confirm('¿Reemplazar la descripción actual por el borrador?'))return;form.elements.description.value=text;};
function completion(){const filled=['make','name','year','description'].filter(k=>form.elements[k].value.trim()).length;$('#completion').textContent=`${filled}/4 datos principales · ${photos.length} fotos`;}form.addEventListener('input',completion);
const market=document.createElement('section');market.className='market-panel';market.innerHTML=`<span class="eyebrow">INTELIGENCIA DE MERCADO</span><h2>Precio con referencias</h2><p>Completa marca, modelo, año, ubicación y versión. Busca anuncios y registra solo vehículos comparables: mismo modelo, versión, condición y año cercano. Los precios anunciados no garantizan el valor de cierre.</p><button type="button" id="research">Buscar referencias en internet</button><div id="search-links" class="search-links"></div><p id="research-status" role="status"></p><div id="research-results"></div><h3>Comparables verificados</h3><div class="fields"><label>Título / modelo<input id="comp-title"></label><label>Enlace del anuncio<input id="comp-url" type="url" placeholder="https://…"></label><label>Precio anunciado<input id="comp-price" type="number" min="1" step="0.01"></label><label>Moneda<select id="comp-currency"><option value="USD">USD</option><option value="BOB">BOB / Bs</option></select></label><label>Año del comparable<input id="comp-year" type="number"></label><label>Kilometraje del comparable<input id="comp-mileage"></label></div><label class="verify-comparable"><input type="checkbox" id="comp-confirm">Revisé el anuncio y confirmé que corresponde al vehículo, mercado, moneda y condición que estoy comparando.</label><button type="button" id="add-comparable">Añadir comparable</button><div id="comparables"></div><div id="valuation" class="valuation"></div><small>Se requieren al menos 3 comparables verificados por moneda. No se convierten monedas ni se aplican descuentos inventados. Guarda el vehículo para conservar las referencias.</small>`;
$('#save').before(market);
function searchLinks(data){const terms=[data.make,data.name,data.version,data.year,data.city,data.country||'Bolivia'].filter(Boolean).join(' ');const links=[['Google','https://www.google.com/search?q='+encodeURIComponent(terms+' venta precio')],['Marketplace','https://www.facebook.com/marketplace/search/?query='+encodeURIComponent(terms)],['Concesionarios','https://www.google.com/search?q='+encodeURIComponent(terms+' concesionario precio')],['Bolmotor','https://www.google.com/search?q='+encodeURIComponent('site:bolmotor.com '+terms)]];$('#search-links').replaceChildren(...links.map(([title,url])=>{const a=document.createElement('a');a.textContent=title;a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;}));}
$('#research').onclick=async()=>{const data=Object.fromEntries(new FormData(form));searchLinks(data);if(!data.make||!data.name){$('#research-status').textContent='Completa primero marca y modelo.';return;}$('#research').disabled=true;$('#research-status').textContent='Consultando anuncios públicos…';$('#research-results').replaceChildren();try{const result=await api('admin/research','POST',data);$('#research-status').textContent=result.notice+' Consulta: '+new Date(result.searchedAt).toLocaleString('es-BO');for(const row of result.results){const article=document.createElement('article'),link=document.createElement('a'),snippet=document.createElement('p'),use=document.createElement('button');link.href=row.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=row.title;snippet.textContent=row.snippet;use.type='button';use.textContent='Revisar como comparable';use.onclick=()=>{$('#comp-title').value=row.title;$('#comp-url').value=row.url;$('#comp-price').value='';$('#comp-confirm').checked=false;$('#comp-price').focus();};article.append(link,snippet,use);$('#research-results').append(article);}}catch(e){$('#research-status').textContent=e.message+' Puedes continuar con los enlaces de búsqueda.';}finally{$('#research').disabled=false;}};
function drawComparables(){$('#comparables').replaceChildren();comparables.forEach((c,i)=>{const row=document.createElement('div');row.className='comparable-row';const text=document.createElement('a');text.textContent=`${c.title} · ${c.currency} ${Number(c.price).toLocaleString('es-BO')} · ${c.year||'Año no indicado'} · ${c.date||''}`;text.href=c.url;text.target='_blank';text.rel='noopener noreferrer';const remove=document.createElement('button');remove.type='button';remove.textContent='Quitar';remove.onclick=()=>{comparables.splice(i,1);drawComparables();};row.append(text,remove);$('#comparables').append(row);});$('#valuation').replaceChildren();for(const currency of ['USD','BOB']){const prices=comparables.filter(c=>c.currency===currency&&c.price>0).map(c=>Number(c.price)).sort((a,b)=>a-b);const box=document.createElement('div');if(prices.length<3){box.textContent=`${currency}: ${prices.length}/3 comparables. Aún no hay suficientes referencias.`;}else{const middle=Math.floor(prices.length/2),median=prices.length%2?prices[middle]:(prices[middle-1]+prices[middle])/2;const title=document.createElement('strong');title.textContent=`${currency} · Mediana anunciada: ${median.toLocaleString('es-BO')}`;const detail=document.createElement('p');detail.textContent=`Rango observado: ${prices[0].toLocaleString('es-BO')} – ${prices.at(-1).toLocaleString('es-BO')} · ${prices.length} anuncios revisados. Revisa valores extremos. Referencia orientativa, no tasación ni precio de cierre.`;const use=document.createElement('button');use.type='button';use.textContent='Usar mediana como precio de referencia';use.onclick=()=>form.elements.price.value=`${currency} ${median.toLocaleString('es-BO')}`;box.append(title,detail,use);}$('#valuation').append(box);}}
$('#add-comparable').onclick=()=>{let url;try{url=new URL($('#comp-url').value);if(!['https:','http:'].includes(url.protocol))throw Error();}catch{$('#research-status').textContent='Añade un enlace HTTP o HTTPS válido.';return;}const price=Number($('#comp-price').value);if(!price||price<=0||!$('#comp-title').value.trim()||!$('#comp-confirm').checked){$('#research-status').textContent='Completa título y precio y confirma que revisaste el anuncio.';return;}if(comparables.some(c=>c.url===url.href)){$('#research-status').textContent='Ese anuncio ya está añadido.';return;}comparables.push({title:$('#comp-title').value,url:url.href,price,currency:$('#comp-currency').value,year:$('#comp-year').value,mileage:$('#comp-mileage').value,date:new Date().toISOString().slice(0,10)});$('#comp-confirm').checked=false;drawComparables();$('#research-status').textContent='Comparable añadido. Guarda el vehículo para conservarlo.';};
const originalOpen=open;open=v=>{originalOpen(v);comparables=structuredClone(v?.comparables||[]);form.elements.country.value=v?.country||'Bolivia';modelOptions();completion();searchLinks(Object.fromEntries(new FormData(form)));drawComparables();$('#research-results').replaceChildren();$('#research-status').textContent='';$('#comp-confirm').checked=false;};
const tools=document.createElement('div');tools.className='inventory-tools';tools.innerHTML='<label>Buscar inventario<input id="admin-search" type="search" placeholder="Marca, modelo, año…"></label><label>Estado<select id="admin-filter"><option value="all">Todos</option><option value="available">Disponibles</option><option value="draft">Borradores</option><option value="sold">Vendidos</option></select></label><button type="button" id="export-inventory">Exportar inventario JSON</button>';$('#list').before(tools);const stats=document.createElement('div');stats.className='admin-stats';tools.before(stats);
function filterRows(){const query=$('#admin-search').value.toLowerCase(),status=$('#admin-filter').value;[...$('#list').children].forEach((row,i)=>{const item=items[i];if(item)row.hidden=!(row.textContent.toLowerCase().includes(query)&&(status==='all'||item.status===status));});}$('#admin-search').oninput=filterRows;$('#admin-filter').onchange=filterRows;
function dashboardExtras(){stats.replaceChildren(...[['Total',items.length],['Disponibles',items.filter(v=>v.status==='available').length],['Borradores',items.filter(v=>v.status==='draft').length],['Vendidos',items.filter(v=>v.status==='sold').length]].map(([label,count])=>{const card=document.createElement('div'),number=document.createElement('strong'),text=document.createElement('span');number.textContent=count;text.textContent=label;card.append(number,text);return card;}));filterRows();}
const originalLoad=load;load=async()=>{await originalLoad();dashboardExtras();};if(!$('#dashboard').hidden)dashboardExtras();
$('#export-inventory').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(items,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='torres-garage-inventario.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
